var outfits=[{"id": "rl-chilly-m35-night-run-20261025-01", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/editorial.jpg", "deck": {"ko": "차콜 셸과 그레이 레이어로 완성한 밤 러닝", "en": "A night run in a charcoal shell and a grey layer.", "de": "Nachtlauf in anthrazitfarbener Shell und grauer Lage."}, "items": ["rl-chilly-m35-night-run-20261025-01.01-outer", "rl-chilly-m35-night-run-20261025-01.02-top", "rl-chilly-m35-night-run-20261025-01.03-bottom", "rl-chilly-m35-night-run-20261025-01.04-hands", "rl-chilly-m35-night-run-20261025-01.05-shoes", "rl-chilly-m35-night-run-20261025-01.06-socks", "rl-chilly-m35-night-run-20261025-01.07-headband"], "article": {"title": "SIDESTEP AT THE PUDDLE", "intro": {"ko": "얇은 비가 내리는 밤, 차콜 셸 안에 하이넥 레이어를 입었어요. 긴 팬츠와 장갑, 넓은 헤드밴드로 쌀쌀한 공기에 맞춰 보세요.", "en": "On a night of fine rain, a high-neck layer goes under the charcoal shell. Full-length trousers, gloves and a wide headband tune the look to the chilly air.", "de": "In einer Nacht mit feinem Regen kommt eine hochgeschlossene Lage unter die anthrazitfarbene Shell. Lange Hose, Handschuhe und ein breites Stirnband stimmen den Look auf die kühle Luft ab."}, "pull": "THE PUDDLE GETS A WIDE BERTH.", "tip": {"ko": "반사 디테일이 있는 옷과 신발을 함께 고르고, 젖은 노면에서는 보폭을 조절하세요.", "en": "Pair clothes and shoes that carry reflective details, and shorten your stride on wet pavement.", "de": "Kleidung und Schuhe mit Reflexdetails kombinieren und auf nassem Pflaster die Schritte verkürzen."}}, "hero": "rl-chilly-m35-night-run-20261025-01.01-outer"}, {"id": "rl-chilly-m35-night-run-20261025-02", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/02/editorial.jpg", "deck": {"ko": "밤비 속 선명한 코발트 러닝 룩", "en": "A vivid cobalt running look in the night rain.", "de": "Ein leuchtender kobaltblauer Lauflook im nächtlichen Regen."}, "items": ["rl-chilly-m35-night-run-20261025-02.01-outer", "rl-chilly-m35-night-run-20261025-02.02-top", "rl-chilly-m35-night-run-20261025-02.03-bottom", "rl-chilly-m35-night-run-20261025-02.04-hands", "rl-chilly-m35-night-run-20261025-02.05-shoes", "rl-chilly-m35-night-run-20261025-02.06-headband"], "article": {"title": "COBALT, HOOD IN HAND", "intro": {"ko": "코발트 셸을 중심으로 블랙 타이츠와 네이비 헤드밴드를 연결했어요. 가벼운 겉옷과 이너의 두께는 달리는 동안의 열감에 맞춰 조절하세요.", "en": "The cobalt shell sets the tone, with black tights and a navy headband linking up around it. Match the weight of the light jacket and the layer beneath to the warmth you build on the run.", "de": "Die kobaltblaue Shell gibt den Ton an, schwarze Tights und ein marineblaues Stirnband knüpfen daran an. Wie dick leichte Jacke und Unterlage sein sollen, richtet sich nach der Wärme, die beim Laufen entsteht."}, "pull": "CATCH THE HOOD, KEEP THE PACE.", "tip": {"ko": "후드와 소매는 움직임을 방해하지 않게 맞춰 주세요.", "en": "Set the hood and sleeves so they never get in the way of your movement.", "de": "Kapuze und Ärmel so einstellen, dass sie die Bewegung nicht behindern."}}, "hero": "rl-chilly-m35-night-run-20261025-02.01-outer"}, {"id": "rl-chilly-m35-night-run-20261025-03", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/editorial.jpg", "deck": {"ko": "올리브와 차콜의 차분한 러닝 레이어", "en": "Calm running layers in olive and charcoal.", "de": "Ruhige Laufschichten in Oliv und Anthrazit."}, "items": ["rl-chilly-m35-night-run-20261025-03.01-outer", "rl-chilly-m35-night-run-20261025-03.02-top", "rl-chilly-m35-night-run-20261025-03.03-bottom", "rl-chilly-m35-night-run-20261025-03.04-hands", "rl-chilly-m35-night-run-20261025-03.05-shoes", "rl-chilly-m35-night-run-20261025-03.06-socks", "rl-chilly-m35-night-run-20261025-03.07-headband"], "article": {"title": "RETIE AND RUN AGAIN", "intro": {"ko": "올리브 셸과 차콜 팬츠를 겹쳐 입고, 밝은 러닝화로 마무리했어요. 장갑과 헤드밴드를 더해 비 오는 밤의 쌀쌀함에 맞췄어요.", "en": "An olive shell layered over charcoal trousers, finished with bright running shoes. Gloves and a headband answer the chill of a rainy night.", "de": "Eine olivgrüne Shell über anthrazitfarbener Hose, abgeschlossen mit hellen Laufschuhen. Handschuhe und Stirnband antworten auf die Kühle einer regnerischen Nacht."}, "pull": "ONE KNOT, THEN BACK INTO THE RAIN.", "tip": {"ko": "출발 전 끈과 발목 주변을 정리하고 젖은 돌길에서는 속도를 낮춰 주세요.", "en": "Before setting off, sort out your laces and everything around the ankles, and slow down on wet cobbles.", "de": "Vor dem Start Schnürsenkel und Knöchelbereich richten und auf nassem Kopfsteinpflaster langsamer laufen."}}, "hero": "rl-chilly-m35-night-run-20261025-03.01-outer"}, {"id": "rl-chilly-m35-night-run-20261025-04", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/04/editorial.jpg", "deck": {"ko": "웜 그레이 셸 안에 더한 플럼 포인트", "en": "A plum accent inside a warm grey shell.", "de": "Ein Pflaumenakzent unter warmgrauer Shell."}, "items": ["rl-chilly-m35-night-run-20261025-04.01-outer", "rl-chilly-m35-night-run-20261025-04.02-top", "rl-chilly-m35-night-run-20261025-04.03-bottom", "rl-chilly-m35-night-run-20261025-04.04-hands", "rl-chilly-m35-night-run-20261025-04.05-headband"], "article": {"title": "PLUM BEFORE THE SIP", "intro": {"ko": "웜 그레이 셸 안으로 플럼 집넥이 살짝 드러나요. 블랙 타이츠와 장갑으로 색을 정돈하고, 지퍼로 목 주변의 열감을 조절하세요.", "en": "A plum zip-neck shows just inside the warm grey shell. Black tights and gloves keep the colours in order, and the zips let you manage the warmth around your neck.", "de": "Unter der warmgrauen Shell blitzt ein pflaumenfarbener Zip-Kragen hervor. Schwarze Tights und Handschuhe ordnen die Farben, und mit den Reißverschlüssen lässt sich die Wärme am Hals regulieren."}, "pull": "A PAUSE, A SIP, A LITTLE PLUM.", "tip": {"ko": "잠시 멈출 때는 바람과 몸의 열감에 맞춰 지퍼를 조절하세요.", "en": "When you stop for a moment, adjust the zips to the wind and to how warm you feel.", "de": "Bei einer kurzen Pause die Reißverschlüsse an Wind und Körperwärme anpassen."}}, "hero": "rl-chilly-m35-night-run-20261025-04.01-outer"}, {"id": "rl-chilly-m35-night-run-20261025-05", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/05/editorial.jpg", "deck": {"ko": "번트 오렌지와 네이비로 잇는 밤 러닝", "en": "A night run linking burnt orange and navy.", "de": "Ein Nachtlauf, der Rostorange und Marineblau verbindet."}, "items": ["rl-chilly-m35-night-run-20261025-05.01-outer", "rl-chilly-m35-night-run-20261025-05.02-bottom", "rl-chilly-m35-night-run-20261025-05.03-hands", "rl-chilly-m35-night-run-20261025-05.04-shoes", "rl-chilly-m35-night-run-20261025-05.05-headband"], "article": {"title": "ORANGE, LOOKING BACK", "intro": {"ko": "번트 오렌지 셸에 네이비 팬츠를 맞춰 움직임이 있는 밤 러닝 룩을 만들었어요. 장갑과 헤드밴드는 어두운 톤으로 이어 주세요.", "en": "A burnt orange shell matched with navy trousers makes a night running look full of movement. Carry the gloves and headband on in dark tones.", "de": "Eine rostorange Shell zu marineblauer Hose ergibt einen bewegten Lauflook für die Nacht. Handschuhe und Stirnband führen ihn in dunklen Tönen weiter."}, "pull": "ONE GLANCE BACK, THEN ON.", "tip": {"ko": "옷의 반사 디테일과 별도로 주변 차량과 노면을 확인하며 달리세요.", "en": "Reflective details aside, keep an eye on traffic and the road surface as you run.", "de": "Unabhängig von Reflexdetails beim Laufen auf Verkehr und Untergrund achten."}}, "hero": "rl-chilly-m35-night-run-20261025-05.01-outer"}];
var items={"rl-chilly-m35-night-run-20261025-01.01-outer": {"id": "rl-chilly-m35-night-run-20261025-01.01-outer", "cat": "outer", "name": {"ko": "차콜 리플렉티브 러닝 셸", "en": "Charcoal reflective running shell", "de": "Anthrazitfarbene reflektierende Lauf-Shelljacke"}, "note": {"ko": "지퍼를 턱 바로 아래까지 올려 높은 칼라로 목을 감싸요. 주머니와 팔 위쪽의 가는 은색 트림이 가로등 빛을 받아 반짝여요.", "en": "Zip it to just below the chin so the tall collar wraps the neck; the narrow silver trim on the pockets and upper arms catches the streetlight.", "de": "Bis knapp unters Kinn schließen, damit der hohe Kragen den Hals umschließt; die schmalen Silberblenden an Taschen und Oberarmen fangen das Laternenlicht."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/products/01-outer.webp", "alt": "차콜 리플렉티브 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-01.02-top": {"id": "rl-chilly-m35-night-run-20261025-01.02-top", "cat": "top", "name": {"ko": "웜 그레이 하이넥 베이스 레이어", "en": "Warm grey high-neck base layer", "de": "Warmgrauer Baselayer mit Stehkragen"}, "note": {"ko": "하이넥이 셸 칼라 위로 살짝 보이게 입어 웜 그레이가 얼굴 아래를 밝혀요. 몸에 붙는 핏이라 셸 안에서 뭉치지 않아요.", "en": "Let the high neck show just above the shell collar so the warm grey lifts the face; the close fit keeps it from bunching under the jacket.", "de": "Den Stehkragen knapp über dem Jackenkragen zeigen, damit das warme Grau das Gesicht aufhellt; die enge Passform verhindert Falten unter der Jacke."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/products/02-top.webp", "alt": "웜 그레이 하이넥 베이스 레이어 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-01.03-bottom": {"id": "rl-chilly-m35-night-run-20261025-01.03-bottom", "cat": "bottom", "name": {"ko": "블랙 테이퍼드 러닝 팬츠", "en": "Black tapered running trousers", "de": "Schwarze, schmal zulaufende Laufhose"}, "note": {"ko": "발목으로 좁아지는 테이퍼드 핏이라 밑단이 젖은 바닥에 끌리지 않아요. 허벅지의 은색 사선이 걸음마다 다리 움직임을 따라가요.", "en": "The taper narrows at the ankle so the hems stay off the wet pavement; the silver slash at the thigh follows each step.", "de": "Zum Knöchel schmal zulaufend, damit die Säume nicht über nasses Pflaster schleifen; der silberne Schrägstreifen am Oberschenkel folgt jedem Schritt."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/products/03-bottom.webp", "alt": "블랙 테이퍼드 러닝 팬츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-01.04-hands": {"id": "rl-chilly-m35-night-run-20261025-01.04-hands", "cat": "hands", "name": {"ko": "블랙 리플렉티브 러닝 장갑", "en": "Black reflective running gloves", "de": "Schwarze reflektierende Laufhandschuhe"}, "note": {"ko": "긴 립 커프를 셸 소매 안으로 밀어 넣어 손목 틈을 막아요. 손등의 은색 점선이 팔을 흔들 때마다 드러나요.", "en": "Push the long ribbed cuffs inside the shell sleeves to close the gap at the wrist; the silver dashes on the backs show with every arm swing.", "de": "Die langen Rippbündchen in die Jackenärmel schieben, damit am Handgelenk keine Lücke bleibt; die silbernen Striche auf dem Handrücken zeigen sich bei jedem Armschwung."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/products/04-hands.webp", "alt": "블랙 리플렉티브 러닝 장갑 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-01.05-shoes": {"id": "rl-chilly-m35-night-run-20261025-01.05-shoes", "cat": "shoes", "name": {"ko": "그레이 메시 러닝화", "en": "Grey mesh running shoes", "de": "Graue Mesh-Laufschuhe"}, "note": {"ko": "두툼한 미드솔이 젖은 돌바닥 위 걸음을 받쳐 줘요. 그레이 메시와 차콜 오버레이가 블랙 팬츠와 흰 양말 사이를 자연스럽게 이어요.", "en": "The thick midsoles soften each step on the wet paving stones, and the grey mesh with charcoal overlays bridges the black trousers and white socks.", "de": "Die dicken Zwischensohlen federn jeden Schritt auf dem nassen Pflaster ab, und das graue Mesh mit anthrazitfarbenen Overlays verbindet schwarze Hose und weiße Socken."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/products/05-shoes.webp", "alt": "그레이 메시 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-01.06-socks": {"id": "rl-chilly-m35-night-run-20261025-01.06-socks", "cat": "socks", "name": {"ko": "화이트 크루 러닝 양말", "en": "White crew running socks", "de": "Weiße Crew-Laufsocken"}, "note": {"ko": "크루 길이로 올려 신어 밑단과 신발 사이 발목을 덮어요. 흰 커프가 어두운 하의 끝에 작은 밝은 선을 더해요.", "en": "Pull them up to crew height to cover the ankle between hem and shoe; the white cuffs add a small bright line below the dark trousers.", "de": "Auf Crew-Höhe hochziehen, damit der Knöchel zwischen Saum und Schuh bedeckt ist; die weißen Bündchen setzen unter der dunklen Hose einen hellen Strich."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/products/06-socks.webp", "alt": "화이트 크루 러닝 양말 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-01.07-headband": {"id": "rl-chilly-m35-night-run-20261025-01.07-headband", "cat": "headwear", "name": {"ko": "블랙 와이드 러닝 헤드밴드", "en": "Black wide running headband", "de": "Schwarzes breites Laufstirnband"}, "note": {"ko": "넓은 폭으로 양쪽 귀를 덮고 이마 위 머리카락을 뒤로 넘겨 고정해요. 셸과 같은 어두운 톤이라 실루엣이 단정해요.", "en": "Wear it wide over both ears and let it hold the hair back off the forehead; the dark tone matches the shell for a tidy outline.", "de": "Breit über beide Ohren tragen und damit die Haare aus der Stirn halten; der dunkle Ton passt zur Shell und hält die Silhouette ruhig."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/01/products/07-headband.webp", "alt": "블랙 와이드 러닝 헤드밴드 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-02.01-outer": {"id": "rl-chilly-m35-night-run-20261025-02.01-outer", "cat": "outer", "name": {"ko": "코발트 후드 러닝 셸", "en": "Cobalt hooded running shell", "de": "Kobaltblaue Lauf-Shelljacke mit Kapuze"}, "note": {"ko": "후드는 목 뒤에 모아 두었다가 빗방울이 굵어지면 한 손으로 당겨 써요. 가슴과 소매의 가는 은색 라인이 선명한 코발트를 더 돋보이게 해요.", "en": "Keep the hood gathered behind the neck and pull it up with one hand when the drops get heavier; fine silver lines on the chest and sleeves sharpen the cobalt.", "de": "Die Kapuze im Nacken gerafft lassen und mit einer Hand hochziehen, wenn die Tropfen dichter werden; feine Silberlinien an Brust und Ärmeln schärfen das Kobaltblau."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/02/products/01-outer.webp", "alt": "코발트 후드 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-02.02-top": {"id": "rl-chilly-m35-night-run-20261025-02.02-top", "cat": "top", "name": {"ko": "블랙 하이넥 베이스 레이어", "en": "Black high-neck base layer", "de": "Schwarzer Baselayer mit Stehkragen"}, "note": {"ko": "하이넥을 끝까지 세워 열린 셸 지퍼 사이로 목을 감싸요. 블랙이라 코발트 아래에서 색이 깔끔하게 정리돼요.", "en": "Stand the high neck all the way up so it wraps the throat inside the open zip; in black it sits cleanly under the cobalt.", "de": "Den Stehkragen ganz aufstellen, damit er im offenen Reißverschluss den Hals umschließt; in Schwarz liegt er ruhig unter dem Kobaltblau."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/02/products/02-top.webp", "alt": "블랙 하이넥 베이스 레이어 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-02.03-bottom": {"id": "rl-chilly-m35-night-run-20261025-02.03-bottom", "cat": "bottom", "name": {"ko": "블랙 러닝 타이츠", "en": "Black running tights", "de": "Schwarze Lauftights"}, "note": {"ko": "발목까지 매끈하게 붙여 입어 젖어도 펄럭이지 않고 다리와 함께 움직여요. 옆선의 은색 사선이 보폭을 따라 보여요.", "en": "Worn smooth down to the ankle, they move with the legs instead of flapping in the wet; the silver angled accent at the side follows your stride.", "de": "Glatt bis zum Knöchel getragen, bewegen sie sich mit den Beinen, statt im Nassen zu flattern; der silberne Schrägakzent an der Seite folgt dem Schritt."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/02/products/03-bottom.webp", "alt": "블랙 러닝 타이츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-02.04-hands": {"id": "rl-chilly-m35-night-run-20261025-02.04-hands", "cat": "hands", "name": {"ko": "블랙 실버 포인트 러닝 장갑", "en": "Black running gloves with silver accents", "de": "Schwarze Laufhandschuhe mit Silberdetails"}, "note": {"ko": "가는 커프를 소매 고무단 안으로 넣어 후드를 잡을 때도 손목이 드러나지 않게 해요. 손등의 은색 선이 손짓을 따라 빛나요.", "en": "Slip the slim cuffs under the elastic sleeve ends so the wrist stays covered even when you reach for the hood; the silver lines on the backs flash with each gesture.", "de": "Die schmalen Bündchen unter die elastischen Ärmelenden schieben, damit das Handgelenk auch beim Griff zur Kapuze bedeckt bleibt; die Silberlinien auf dem Handrücken blitzen bei jeder Geste."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/02/products/04-hands.webp", "alt": "블랙 실버 포인트 러닝 장갑 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-02.05-shoes": {"id": "rl-chilly-m35-night-run-20261025-02.05-shoes", "cat": "shoes", "name": {"ko": "차콜 러닝화", "en": "Charcoal running shoes", "de": "Anthrazitfarbene Laufschuhe"}, "note": {"ko": "차콜 메시가 블랙 타이츠와 이어져 다리 라인이 길어 보여요. 끈은 발등에 맞게 단단히 묶어 젖은 보도에서도 발이 흔들리지 않게 해요.", "en": "The charcoal mesh runs on from the black tights and lengthens the leg line; lace them firmly over the instep so the foot stays steady on wet pavement.", "de": "Das anthrazitfarbene Mesh setzt die schwarzen Tights fort und streckt die Beinlinie; über dem Spann fest schnüren, damit der Fuß auf nassem Gehweg ruhig steht."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/02/products/05-shoes.webp", "alt": "차콜 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-02.06-headband": {"id": "rl-chilly-m35-night-run-20261025-02.06-headband", "cat": "headwear", "name": {"ko": "네이비 와이드 러닝 헤드밴드", "en": "Navy wide running headband", "de": "Marineblaues breites Laufstirnband"}, "note": {"ko": "도톰한 네이비 헤드밴드를 귀 위까지 내려 쓰고 젖은 앞머리를 올려 고정해요. 코발트와 같은 블루 계열이라 색이 자연스럽게 이어져요.", "en": "Pull the thick navy band down over the ears and let it keep wet hair off the face; staying in the blue family, it links naturally to the cobalt.", "de": "Das dicke marineblaue Band über die Ohren ziehen und nasse Haare damit aus dem Gesicht halten; als Blauton schließt es natürlich an das Kobalt an."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/02/products/06-headband.webp", "alt": "네이비 와이드 러닝 헤드밴드 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-03.01-outer": {"id": "rl-chilly-m35-night-run-20261025-03.01-outer", "cat": "outer", "name": {"ko": "올리브 러닝 셸", "en": "Olive running shell", "de": "Olivgrüne Lauf-Shelljacke"}, "note": {"ko": "지퍼를 가슴까지 올리고 후드는 내려 등 뒤에 둬요. 차분한 올리브 위로 어깨의 은색 트림이 가로등 아래에서 살짝 빛나요.", "en": "Zip it to the chest and leave the hood down at the back; on the muted olive, the silver trim at the shoulders glints under the streetlights.", "de": "Bis zur Brust schließen und die Kapuze hinten liegen lassen; auf dem gedeckten Oliv glänzen die Silberblenden an den Schultern unter den Laternen."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/products/01-outer.webp", "alt": "올리브 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-03.02-top": {"id": "rl-chilly-m35-night-run-20261025-03.02-top", "cat": "top", "name": {"ko": "블랙 집넥 베이스 레이어", "en": "Black zip-neck base layer", "de": "Schwarzer Baselayer mit Reißverschlusskragen"}, "note": {"ko": "짧은 지퍼를 끝까지 올려 하이넥으로 목을 덮어요. 블랙이라 올리브 셸의 열린 앞판 사이로 깔끔하게 보여요.", "en": "Run the short zip all the way up so the high neck covers the throat; in black it reads cleanly through the open front of the olive shell.", "de": "Den kurzen Reißverschluss ganz hochziehen, damit der Stehkragen den Hals bedeckt; in Schwarz wirkt er klar im offenen Vorderteil der olivgrünen Shell."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/products/02-top.webp", "alt": "블랙 집넥 베이스 레이어 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-03.03-bottom": {"id": "rl-chilly-m35-night-run-20261025-03.03-bottom", "cat": "bottom", "name": {"ko": "차콜 슬림 러닝 팬츠", "en": "Charcoal slim running trousers", "de": "Anthrazitfarbene schmale Laufhose"}, "note": {"ko": "테이퍼드 밑단이 발목에 붙어 끈을 묶으려 몸을 숙여도 걸리지 않아요. 허벅지와 종아리의 은색 사선이 차콜 위에 가볍게 떠요.", "en": "The tapered cuffs sit close at the ankle, so nothing gets in the way when you crouch to tie a lace; silver slashes at thigh and calf float lightly on the charcoal.", "de": "Die schmalen Beinabschlüsse liegen eng am Knöchel, sodass beim Hinknien zum Schnüren nichts im Weg ist; silberne Schrägstreifen an Oberschenkel und Wade liegen leicht auf dem Anthrazit."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/products/03-bottom.webp", "alt": "차콜 슬림 러닝 팬츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-03.04-hands": {"id": "rl-chilly-m35-night-run-20261025-03.04-hands", "cat": "hands", "name": {"ko": "블랙 리플렉티브 스트라이프 장갑", "en": "Black running gloves with reflective stripes", "de": "Schwarze Laufhandschuhe mit Reflexstreifen"}, "note": {"ko": "장갑을 낀 채로도 끈을 묶을 수 있게 손에 꼭 맞는 사이즈를 골라요. 긴 커프는 셸 소매 끝 위로 덮어 써요.", "en": "Choose a snug fit so you can tie your laces with the gloves still on, and wear the long cuffs over the ends of the shell sleeves.", "de": "Eng anliegend wählen, damit sich die Schnürsenkel mit Handschuhen binden lassen, und die langen Bündchen über die Ärmelenden der Shell ziehen."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/products/04-hands.webp", "alt": "블랙 리플렉티브 스트라이프 장갑 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-03.05-shoes": {"id": "rl-chilly-m35-night-run-20261025-03.05-shoes", "cat": "shoes", "name": {"ko": "오프화이트 그레이 러닝화", "en": "Off-white and grey running shoes", "de": "Offwhite-graue Laufschuhe"}, "note": {"ko": "오프화이트 러닝화가 어두운 하의 아래에서 가장 밝은 포인트가 돼요. 출발 전 끈을 다시 조여 두툼한 쿠션 위에서 발이 밀리지 않게 해요.", "en": "The off-white shoes become the brightest point beneath the dark trousers; retighten the laces before you go so the foot stays put on the thick cushioning.", "de": "Die offwhite Schuhe werden unter der dunklen Hose zum hellsten Punkt; vor dem Start nachschnüren, damit der Fuß auf der dicken Dämpfung nicht rutscht."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/products/05-shoes.webp", "alt": "오프화이트 그레이 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-03.06-socks": {"id": "rl-chilly-m35-night-run-20261025-03.06-socks", "cat": "socks", "name": {"ko": "화이트 앵클 러닝 양말", "en": "White ankle running socks", "de": "Weiße knöchelhohe Laufsocken"}, "note": {"ko": "발목 높이의 흰 양말이 신발 칼라 위로 살짝 보여 오프화이트 러닝화와 이어져요. 밑단과 신발 사이 작은 틈을 가볍게 메워요.", "en": "The white ankle socks peek just above the shoe collar and carry the off-white upward, filling the small gap between hem and shoe.", "de": "Die weißen Knöchelsocken blitzen knapp über dem Schuhrand hervor, führen das Offwhite nach oben und schließen die kleine Lücke zwischen Saum und Schuh."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/products/06-socks.webp", "alt": "화이트 앵클 러닝 양말 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-03.07-headband": {"id": "rl-chilly-m35-night-run-20261025-03.07-headband", "cat": "headwear", "name": {"ko": "차콜 멜란지 러닝 헤드밴드", "en": "Charcoal heather running headband", "de": "Anthrazitmeliertes Laufstirnband"}, "note": {"ko": "멜란지 차콜 헤드밴드를 이마 위로 낮게 써서 귀를 덮어요. 부드러운 기모 질감이 매끈한 셸과 대비를 줘요.", "en": "Wear the heather charcoal band low on the forehead so it covers the ears; its soft brushed texture contrasts with the smooth shell.", "de": "Das melierte anthrazitfarbene Band tief in der Stirn tragen, damit es die Ohren bedeckt; die weich angeraute Oberfläche kontrastiert mit der glatten Shell."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/03/products/07-headband.webp", "alt": "차콜 멜란지 러닝 헤드밴드 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-04.01-outer": {"id": "rl-chilly-m35-night-run-20261025-04.01-outer", "cat": "outer", "name": {"ko": "웜 그레이 리플렉티브 러닝 셸", "en": "Warm grey reflective running shell", "de": "Warmgraue reflektierende Lauf-Shelljacke"}, "note": {"ko": "셸 지퍼를 가슴 아래까지 열어 플럼 이너가 보이게 하고, 멈춰 설 때는 끝까지 올려요. 어깨를 가로지르는 은색 곡선 파이핑이 빛을 받아요.", "en": "Open the shell to below the chest so the plum layer shows, and zip it right up when you stop; the curved silver piping across the shoulders catches the light.", "de": "Die Shell bis unter die Brust öffnen, damit die pflaumenfarbene Lage zu sehen ist, und beim Anhalten ganz schließen; die geschwungenen Silberpaspeln über den Schultern fangen das Licht."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/04/products/01-outer.webp", "alt": "웜 그레이 리플렉티브 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-04.02-top": {"id": "rl-chilly-m35-night-run-20261025-04.02-top", "cat": "top", "name": {"ko": "플럼 집넥 러닝 베이스 레이어", "en": "Plum zip-neck running base layer", "de": "Pflaumenfarbener Lauf-Baselayer mit Reißverschlusskragen"}, "note": {"ko": "달리는 동안 짧은 앞 지퍼를 조금 내려 열을 빼고, 쉴 때는 올려 목을 덮어요. 딥 플럼이 웜 그레이와 블랙 사이에서 조용한 포인트가 돼요.", "en": "Lower the short front zip a little while running to let heat out, and raise it to cover the neck when you rest; deep plum is a quiet accent between warm grey and black.", "de": "Beim Laufen den kurzen Reißverschluss etwas öffnen, um Wärme abzulassen, und in der Pause hochziehen; dunkles Pflaume setzt zwischen Warmgrau und Schwarz einen leisen Akzent."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/04/products/02-top.webp", "alt": "플럼 집넥 러닝 베이스 레이어 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-04.03-bottom": {"id": "rl-chilly-m35-night-run-20261025-04.03-bottom", "cat": "bottom", "name": {"ko": "블랙 풀렝스 러닝 타이츠", "en": "Black full-length running tights", "de": "Schwarze lange Lauftights"}, "note": {"ko": "허리를 셸 밑단 아래로 단정히 맞춰 입고, 허벅지 바깥의 작은 은색 사선이 보이게 해요. 블랙이라 플럼과 그레이를 차분하게 받쳐 줘요.", "en": "Sit the waist neatly under the shell hem and let the small silver accent on the outer thigh show; the black grounds the plum and grey.", "de": "Den Bund ordentlich unter dem Jackensaum tragen und den kleinen Silberakzent am äußeren Oberschenkel zeigen; das Schwarz erdet Pflaume und Grau."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/04/products/03-bottom.webp", "alt": "블랙 풀렝스 러닝 타이츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-04.04-hands": {"id": "rl-chilly-m35-night-run-20261025-04.04-hands", "cat": "hands", "name": {"ko": "블랙 파이핑 러닝 장갑", "en": "Black running gloves with reflective piping", "de": "Schwarze Laufhandschuhe mit Reflexpaspel"}, "note": {"ko": "손목에 꼭 맞아 잠시 멈춰 지퍼를 조절할 때도 벗을 필요가 없어요. 손등의 은색 선이 셸의 파이핑과 짝을 이뤄요.", "en": "They fit close at the wrist, so you can work the zips during a pause without taking them off; the silver stripe on the back pairs with the shell's piping.", "de": "Am Handgelenk eng anliegend, sodass sich die Reißverschlüsse in der Pause bedienen lassen, ohne sie auszuziehen; der Silberstreifen auf dem Handrücken passt zu den Paspeln der Shell."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/04/products/04-hands.webp", "alt": "블랙 파이핑 러닝 장갑 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-04.05-headband": {"id": "rl-chilly-m35-night-run-20261025-04.05-headband", "cat": "headwear", "name": {"ko": "블랙 이어워머 헤드밴드", "en": "Black ear-warmer running headband", "de": "Schwarzes Laufstirnband als Ohrenwärmer"}, "note": {"ko": "귀를 넓게 덮는 이어워머 헤드밴드라 멈춰 선 순간에도 귀가 금방 차가워지지 않아요. 젖은 머리 위로 깊게 눌러 써요.", "en": "Cut as an ear warmer, it covers the ears broadly so they don't chill the moment you stand still; pull it down firmly over damp hair.", "de": "Als Ohrenwärmer geschnitten, bedeckt es die Ohren breit, damit sie beim Stehenbleiben nicht sofort auskühlen; fest über das feuchte Haar ziehen."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/04/products/05-headband.webp", "alt": "블랙 이어워머 헤드밴드 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-05.01-outer": {"id": "rl-chilly-m35-night-run-20261025-05.01-outer", "cat": "outer", "name": {"ko": "번트 오렌지 러닝 셸", "en": "Burnt orange running shell", "de": "Rostorange Lauf-Shelljacke"}, "note": {"ko": "어깨에서 등과 소매로 이어지는 은색 솔기 라인이 뒷모습을 살려요. 소매 탭으로 손목 둘레를 알맞게 조여요.", "en": "The silver seam line running from the shoulder down the back and sleeve shapes the view from behind; use the cuff tabs to snug each sleeve at the wrist.", "de": "Die silberne Nahtlinie von der Schulter über Rücken und Ärmel zeichnet die Rückansicht; mit den Ärmellaschen jedes Bündchen am Handgelenk passend schließen."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/05/products/01-outer.webp", "alt": "번트 오렌지 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-05.02-bottom": {"id": "rl-chilly-m35-night-run-20261025-05.02-bottom", "cat": "bottom", "name": {"ko": "네이비 슬림 러닝 팬츠", "en": "Navy slim running trousers", "de": "Marineblaue schmale Laufhose"}, "note": {"ko": "슬림한 테이퍼드 핏이 발목에서 좁아져 셸의 넉넉한 밑단과 균형을 맞춰요. 허벅지 바깥의 은색 사선이 걸음마다 드러나요.", "en": "The slim taper narrows at the ankle and balances the shell's roomier hem; the silver diagonal on the outer thigh shows with every step.", "de": "Die schmale Form läuft zum Knöchel zu und gleicht den weiteren Saum der Shell aus; die silberne Diagonale am äußeren Oberschenkel zeigt sich bei jedem Schritt."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/05/products/02-bottom.webp", "alt": "네이비 슬림 러닝 팬츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-05.03-hands": {"id": "rl-chilly-m35-night-run-20261025-05.03-hands", "cat": "hands", "name": {"ko": "차콜 리플렉티브 러닝 장갑", "en": "Charcoal reflective running gloves", "de": "Anthrazitfarbene reflektierende Laufhandschuhe"}, "note": {"ko": "차콜 장갑 커프를 셸 소매 안으로 넣어 손목을 덮어요. 어두운 톤이 번트 오렌지를 더 선명하게 보이게 해요.", "en": "Tuck the charcoal cuffs inside the shell sleeves to keep the wrists covered; the dark tone makes the burnt orange look brighter.", "de": "Die anthrazitfarbenen Bündchen in die Shell-Ärmel stecken, damit die Handgelenke bedeckt bleiben; der dunkle Ton lässt das Rostorange leuchtender wirken."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/05/products/03-hands.webp", "alt": "차콜 리플렉티브 러닝 장갑 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-05.04-shoes": {"id": "rl-chilly-m35-night-run-20261025-05.04-shoes", "cat": "shoes", "name": {"ko": "그레이 쿠션 러닝화", "en": "Grey cushioned running shoes", "de": "Graue gedämpfte Laufschuhe"}, "note": {"ko": "두툼한 오프화이트 미드솔이 젖은 돌바닥에서 발걸음을 부드럽게 받쳐요. 그레이 톤이 네이비 밑단 아래를 가볍게 마무리해요.", "en": "Thick off-white midsoles cushion each stride on the wet paving, and the grey finishes lightly below the navy hems.", "de": "Dicke offwhite Zwischensohlen dämpfen jeden Laufschritt auf dem nassen Pflaster, und das Grau schließt leicht unter den marineblauen Säumen ab."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/05/products/04-shoes.webp", "alt": "그레이 쿠션 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-m35-night-run-20261025-05.05-headband": {"id": "rl-chilly-m35-night-run-20261025-05.05-headband", "cat": "headwear", "name": {"ko": "차콜 와이드 러닝 헤드밴드", "en": "Charcoal wide running headband", "de": "Anthrazitfarbenes breites Laufstirnband"}, "note": {"ko": "차콜 헤드밴드로 귀를 덮고 머리를 뒤로 넘겨 고개를 돌려도 흘러내리지 않게 해요. 장갑과 같은 어두운 톤으로 맞춰요.", "en": "Cover the ears with the charcoal band and sweep the hair back so nothing slips when you turn your head; keep it in the same dark tone as the gloves.", "de": "Mit dem anthrazitfarbenen Band die Ohren bedecken und die Haare zurückstreichen, damit beim Umdrehen nichts verrutscht; im selben dunklen Ton wie die Handschuhe."}, "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/running-20261025/05/products/05-headband.webp", "alt": "차콜 와이드 러닝 헤드밴드 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}};
